    sentences: [
      { id: 'u36_s1', index: 1, unitId: 36, vietnamese: 'Hôm qua tôi bị đau đầu dữ dội nên tôi đã đến hiệu thuốc.', clues: [{ term: 'severe headache', type: 'n', meaning: 'đau đầu dữ dội' }, { term: 'pharmacy', type: 'n', meaning: 'hiệu thuốc' }], english: 'Yesterday I had a severe headache, so I went to the pharmacy.' },
      { id: 'u36_s2', index: 2, unitId: 36, vietnamese: 'Bác sĩ khuyên anh ấy nên uống nhiều nước và nghỉ ngơi.', clues: [{ term: 'advise', type: 'v', meaning: 'khuyên' }, { term: 'rest', type: 'v/n', meaning: 'nghỉ ngơi' }], english: 'The doctor advised him to drink plenty of water and rest.' },
      { id: 'u36_s3', index: 3, unitId: 36, vietnamese: 'Bạn đã uống thuốc cảm cúm mà tôi mua cho bạn chưa?', clues: [{ term: 'flu medicine', type: 'n', meaning: 'thuốc cảm cúm' }], english: 'Have you taken the flu medicine that I bought for you?' },
      { id: 'u36_s4', index: 4, unitId: 36, vietnamese: 'Cô ấy đang đợi ở phòng cấp cứu vì con trai cô ấy bị gãy tay.', clues: [{ term: 'emergency room', type: 'n', meaning: 'phòng cấp cứu' }, { term: "break one's arm", type: 'v-phrase', meaning: 'gãy tay' }], english: 'She is waiting in the emergency room because her son broke his arm.' },
      { id: 'u36_s5', index: 5, unitId: 36, vietnamese: 'Nếu bạn cảm thấy chóng mặt, bạn nên ngồi xuống ngay lập tức.', clues: [{ term: 'dizzy', type: 'adj', meaning: 'chóng mặt' }, { term: 'immediately', type: 'adv', meaning: 'ngay lập tức' }], english: 'If you feel dizzy, you should sit down immediately.' },
      { id: 'u36_s6', index: 6, unitId: 36, vietnamese: 'Đơn thuốc này cần được mang đến dược sĩ trước buổi trưa.', clues: [{ term: 'prescription', type: 'n', meaning: 'đơn thuốc' }, { term: 'pharmacist', type: 'n', meaning: 'dược sĩ' }], english: 'This prescription needs to be taken to the pharmacist before noon.' },
      { id: 'u36_s7', index: 7, unitId: 36, vietnamese: 'Bệnh nhân đã được phẫu thuật thành công vào sáng nay.', clues: [{ term: 'patient', type: 'n', meaning: 'bệnh nhân' }, { term: 'surgery', type: 'n', meaning: 'phẫu thuật' }], english: 'The patient was successfully operated on this morning.' },
      { id: 'u36_s8', index: 8, unitId: 36, vietnamese: 'Tôi bị dị ứng với hải sản, nên tôi không thể ăn món này.', clues: [{ term: 'allergic to', type: 'adj-phrase', meaning: 'bị dị ứng với' }], english: 'I am allergic to seafood, so I cannot eat this dish.' },
      { id: 'u36_s9', index: 9, unitId: 36, vietnamese: 'Mặc dù anh ấy bị sốt cao, anh ấy vẫn đi làm.', clues: [{ term: 'high fever', type: 'n', meaning: 'sốt cao' }], english: 'Although he had a high fever, he still went to work.' },
      { id: 'u36_s10', index: 10, unitId: 36, vietnamese: 'Bạn có biết phòng khám nha khoa gần nhất ở đâu không?', clues: [{ term: 'dental clinic', type: 'n', meaning: 'phòng khám nha khoa' }], english: 'Do you know where the nearest dental clinic is?' },
      { id: 'u36_s11', index: 11, unitId: 36, vietnamese: 'Y tá sẽ đo huyết áp của bạn trước khi bạn gặp bác sĩ.', clues: [{ term: 'nurse', type: 'n', meaning: 'y tá' }, { term: 'measure blood pressure', type: 'v-phrase', meaning: 'đo huyết áp' }], english: 'The nurse will measure your blood pressure before you see the doctor.' },
      { id: 'u36_s12', index: 12, unitId: 36, vietnamese: 'Thuốc giảm đau này có thể gây buồn ngủ.', clues: [{ term: 'painkiller', type: 'n', meaning: 'thuốc giảm đau' }, { term: 'cause drowsiness', type: 'v-phrase', meaning: 'gây buồn ngủ' }], english: 'This painkiller may cause drowsiness.' },
      { id: 'u36_s13', index: 13, unitId: 36, vietnamese: 'Khi tôi đến bệnh viện, họ đang chuyển bệnh nhân sang phòng khác.', clues: [{ term: 'move / transfer', type: 'v', meaning: 'chuyển' }], english: 'When I arrived at the hospital, they were moving the patient to another room.' },
      { id: 'u36_s14', index: 14, unitId: 36, vietnamese: 'Ông của tôi phải kiểm tra sức khỏe định kỳ mỗi sáu tháng.', clues: [{ term: 'regular health check-up', type: 'n-phrase', meaning: 'kiểm tra sức khỏe định kỳ' }], english: 'My grandfather has to get a regular health check-up every six months.' },
      { id: 'u36_s15', index: 15, unitId: 36, vietnamese: 'Cô ấy không thể nói được vì cô ấy bị đau họng tồi tệ.', clues: [{ term: 'sore throat', type: 'n', meaning: 'đau họng' }], english: "She couldn't speak because she had a terrible sore throat." },
      { id: 'u36_s16', index: 16, unitId: 36, vietnamese: 'Bạn nên gọi xe cấp cứu nếu tình trạng trở nên tồi tệ hơn.', clues: [{ term: 'ambulance', type: 'n', meaning: 'xe cấp cứu' }, { term: 'condition', type: 'n', meaning: 'tình trạng' }], english: 'You should call an ambulance if the condition gets worse.' },
      { id: 'u36_s17', index: 17, unitId: 36, vietnamese: 'Vết thương của anh ấy đang chảy máu, nhưng nó không quá nghiêm trọng.', clues: [{ term: 'wound', type: 'n', meaning: 'vết thương' }, { term: 'bleed', type: 'v', meaning: 'chảy máu' }], english: 'His wound is bleeding, but it is not too serious.' },
      { id: 'u36_s18', index: 18, unitId: 36, vietnamese: 'Bác sĩ đã chẩn đoán cô ấy mắc bệnh tiểu đường vào năm ngoái.', clues: [{ term: 'diagnose', type: 'v', meaning: 'chẩn đoán' }, { term: 'diabetes', type: 'n', meaning: 'bệnh tiểu đường' }], english: 'The doctor diagnosed her with diabetes last year.' },
      { id: 'u36_s19', index: 19, unitId: 36, vietnamese: 'Chúng tôi sẽ đi thăm dì của tôi ở bệnh viện vào ngày mai.', clues: [{ term: 'visit', type: 'v', meaning: 'đi thăm' }], english: 'We will visit my aunt in the hospital tomorrow.' },
      { id: 'u36_s20', index: 20, unitId: 36, vietnamese: 'Sau khi uống thuốc kháng sinh, tôi cảm thấy tốt hơn nhiều.', clues: [{ term: 'antibiotics', type: 'n', meaning: 'thuốc kháng sinh' }], english: 'After taking antibiotics, I felt much better.' },
      { id: 'u36_s21', index: 21, unitId: 36, vietnamese: 'Anh ấy bị ho dai dẳng trong suốt hai tuần qua.', clues: [{ term: 'persistent cough', type: 'n-phrase', meaning: 'ho dai dẳng' }], english: 'He has had a persistent cough for the past two weeks.' },
      { id: 'u36_s22', index: 22, unitId: 36, vietnamese: 'Việc tiêm vắc-xin rất quan trọng để bảo vệ bạn khỏi virus.', clues: [{ term: 'get vaccinated', type: 'v-phrase', meaning: 'tiêm vắc-xin' }, { term: 'protect', type: 'v', meaning: 'bảo vệ' }], english: 'Getting vaccinated is very important to protect yourself from the virus.' },
      { id: 'u36_s23', index: 23, unitId: 36, vietnamese: 'Hiệu thuốc đóng cửa vào lúc 9 giờ tối, vì vậy hãy nhanh lên.', clues: [{ term: 'close', type: 'v', meaning: 'đóng cửa' }, { term: 'hurry up', type: 'v', meaning: 'nhanh lên' }], english: 'The pharmacy closes at 9 PM, so hurry up.' },
      { id: 'u36_s24', index: 24, unitId: 36, vietnamese: 'Nếu cô ấy không ăn kiêng, sức khỏe của cô ấy sẽ suy giảm.', clues: [{ term: 'go on a diet', type: 'v-phrase', meaning: 'ăn kiêng' }, { term: 'decline', type: 'v', meaning: 'suy giảm' }], english: "If she doesn't go on a diet, her health will decline." },
      { id: 'u36_s25', index: 25, unitId: 36, vietnamese: 'Xin lỗi, bạn có bán băng gạc ở đây không?', clues: [{ term: 'bandages', type: 'n', meaning: 'băng gạc' }], english: 'Excuse me, do you sell bandages here?' },
      { id: 'u36_s26', index: 26, unitId: 36, vietnamese: 'Tôi cảm thấy buồn nôn sau khi ăn thức ăn ở nhà hàng đó.', clues: [{ term: 'nauseous', type: 'adj', meaning: 'buồn nôn' }], english: 'I felt nauseous after eating the food at that restaurant.' },
      { id: 'u36_s27', index: 27, unitId: 36, vietnamese: 'Cơn đau ở ngực của anh ấy đã giảm bớt nhờ vào thuốc.', clues: [{ term: 'ease / decrease', type: 'v', meaning: 'giảm bớt' }, { term: 'thanks to', type: 'prep', meaning: 'nhờ vào' }], english: 'The pain in his chest has eased thanks to the medicine.' },
      { id: 'u36_s28', index: 28, unitId: 36, vietnamese: 'Bệnh viện này được trang bị những thiết bị y tế hiện đại nhất.', clues: [{ term: 'be equipped with', type: 'v-phrase', meaning: 'được trang bị' }, { term: 'medical equipment', type: 'n', meaning: 'thiết bị y tế' }], english: 'This hospital is equipped with the most modern medical equipment.' },
      { id: 'u36_s29', index: 29, unitId: 36, vietnamese: 'Bạn có bảo hiểm y tế để chi trả cho ca phẫu thuật này không?', clues: [{ term: 'health insurance', type: 'n', meaning: 'bảo hiểm y tế' }, { term: 'cover / pay for', type: 'v', meaning: 'chi trả' }], english: 'Do you have health insurance to cover this surgery?' },
      { id: 'u36_s30', index: 30, unitId: 36, vietnamese: 'Cô ấy đã hồi phục hoàn toàn sau vụ tai nạn.', clues: [{ term: 'fully recover', type: 'v-phrase', meaning: 'hồi phục hoàn toàn' }], english: 'She has fully recovered from the accident.' }
    ]
